@app.post("/api/search")
async def search_endpoint(request: Request):
    body = await request.json()
    query = body.get("query", "")
    domain = body.get("domain", "")
    num_results = int(body.get("num_results", 10))

    exa = Exa(EXA_API_KEY)

    kwargs = {
        "num_results": num_results,
        "type": "neural",
        "contents": {
            "summary": {
                "query": "mindent magyarul írj"
            },
            "extras": {
                "links": 1
            }
        }
    }

    if domain:
        kwargs["include_domains"] = [domain]

    result = exa.search_and_contents(query, **kwargs)

    results_list = []
    for r in result.results:
        summary_text = ""
        if hasattr(r, "summary") and r.summary:
            summary_text = r.summary
        results_list.append({
            "title": getattr(r, "title", ""),
            "url": getattr(r, "url", ""),
            "summary": summary_text,
            "score": getattr(r, "score", None),
            "published_date": getattr(r, "published_date", None),
        })

    return {"results": results_list, "count": len(results_list)}

@app.post("/api/analyze")
async def analyze_endpoint(request: Request):
    body = await request.json()
    summaries = body.get("summaries", "")
    system_prompt = body.get("system_prompt", "Részletes magyar összefoglalót írj.")
    query = body.get("query", "")

    client = Cerebras(api_key=CEREBRAS_API_KEY)

    user_message = (
        f"Az alábbi keresési lekérdezés eredményeit kaptam: '{query}'\n\n"
        f"Az Exa keresőmotor az alábbi összefoglalókat adta vissza az egyes találatokról:\n\n"
        f"{summaries}\n\n"
        f"Kérlek, írj egy részletes, átfogó, jól strukturált magyar nyelvű elemzést és összefoglalást "
        f"az összes fenti információ alapján. Térj ki a főbb témákra, trendekre, és a legfontosabb "
        f"alkalmazásokra. Az összefoglalónak informatívnak és könnyen érthetőnek kell lennie."
    )

    stream = client.chat.completions.create(
        messages=[
            {
                "role": "system",
                "content": system_prompt
            },
            {
                "role": "user",
                "content": user_message
            }
        ],
        model="qwen-3-235b-a22b-instruct-2507",
        stream=True,
        max_completion_tokens=20000,
        temperature=1.01,
        top_p=0.8
    )

    async def event_generator():
        for chunk in stream:
            delta = chunk.choices[0].delta
            content = delta.content if delta.content else ""
            if content:
                data = json.dumps({"content": content})
                yield f"data: {data}\n\n"
        yield "data: [DONE]\n\n"

    return StreamingResponse(event_generator(), media_type="text/event-stream")
